import assert from 'node:assert/strict';
const {Buffer,HTTPParser}=await import('file:///tmp/niva-http-browser-probe.mjs');

function parse(type, raw) {
  const parser = new HTTPParser(type);
  const result = { headers: null, trailerHeaders: [], body: '', completed: 0 };
  parser.onHeadersComplete = info => { result.headers = info; };
  parser.onHeaders = fields => { result.trailerHeaders.push(fields.slice()); };
  parser.onBody = chunk => { result.body += chunk.toString(); };
  parser.onMessageComplete = () => { result.completed += 1; };
  // Deliberately split start line, headers, and chunk framing across input writes.
  const sizes = [1, 4, 7, 2, 5, 3, 8];
  let cursor = 0, idx = 0;
  while (cursor < raw.length) {
    const end = Math.min(raw.length, cursor + sizes[idx++ % sizes.length]);
    const chunk = Buffer.from(raw.slice(cursor, end));
    const consumed = parser.execute(chunk);
    if (consumed instanceof Error) throw consumed;
    assert.equal(consumed, chunk.length);
    cursor = end;
  }
  return result;
}
const request = parse(HTTPParser.REQUEST,
  'POST /upload HTTP/1.1\r\nHost: example.test\r\nTransfer-Encoding: chunked\r\n\r\n4\r\nWiki\r\n5\r\npedia\r\n0\r\nX-Checksum: 7\r\n\r\n');
assert.equal(request.headers.method, 'POST');
assert.equal(request.headers.url, '/upload');
assert.equal(request.body, 'Wikipedia');
assert.deepEqual(request.trailerHeaders[0], ['X-Checksum', '7']);
assert.equal(request.completed, 1);
const response = parse(HTTPParser.RESPONSE,
  'HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n3\r\none\r\n3\r\ntwo\r\n0\r\nX-Trace: done\r\n\r\n');
assert.equal(response.headers.statusCode, 200);
assert.equal(response.headers.statusMessage, 'OK');
assert.equal(response.body, 'onetwo');
assert.deepEqual(response.trailerHeaders[0], ['X-Trace', 'done']);
assert.equal(response.completed, 1);
console.log(JSON.stringify({request:{method:request.headers.method,url:request.headers.url,body:request.body,trailer:request.trailerHeaders[0],completed:request.completed},response:{status:response.headers.statusCode,body:response.body,trailer:response.trailerHeaders[0],completed:response.completed}}));

