use std::{env, fs};
#[cfg(feature = "dns-codec")]
use dns_packet::{Header, MessageType, QueryType, Question, Reader, Resource, ResponseData, Writer};

#[cfg(feature = "dns-codec")]
fn parsed_checksum(packet: &[u8]) -> Result<u64, String> {
    let mut reader = Reader::new(packet);
    let header = reader.read_header().ok_or("header")?;
    let mut checksum = header.id as u64 + header.answer_count as u64 + header.question_count as u64;
    for _ in 0..header.question_count {
        let q = reader.read_question().ok_or("question")?;
        let (name, qtype, qclass) = (q.name.to_owned(), q.qtype, q.qclass);
        checksum = checksum.wrapping_add(name.bytes().map(u64::from).sum::<u64>() + qtype as u64 + qclass as u64);
    }
    for _ in 0..header.answer_count {
        let rr = reader.read_resource().ok_or("resource")?;
        let (name, qtype, qclass, ttl, len) = (rr.name.to_owned(), rr.qtype, rr.qclass, rr.time_to_live, rr.data_len as usize);
        let start = reader.offset;
        let end = start.checked_add(len).ok_or("overflow")?;
        let raw = reader.packet.get(start..end).ok_or("rdata bounds")?;
        checksum = checksum.wrapping_add(name.bytes().map(u64::from).sum::<u64>() + qtype as u64 + qclass as u64 + ttl as u64);
        match qtype {
            1 => {
                if len != 4 { return Err("A RDATA length".into()); }
                checksum = checksum.wrapping_add(raw.iter().map(|b| *b as u64).sum::<u64>());
            }
            5 => {
                let cname = reader.read_name().ok_or("CNAME RDATA name")?.to_owned();
                if reader.offset > end { return Err("CNAME exceeds rdlength".into()); }
                checksum = checksum.wrapping_add(cname.bytes().map(u64::from).sum::<u64>());
            }
            16 => {
                let mut i = start;
                while i < end {
                    let chunk_len = reader.packet[i] as usize;
                    i += 1;
                    let chunk_end = i.checked_add(chunk_len).ok_or("TXT overflow")?;
                    let chunk = reader.packet.get(i..chunk_end).ok_or("TXT chunk bounds")?;
                    checksum = checksum.wrapping_add(chunk_len as u64 + chunk.iter().map(|b| *b as u64).sum::<u64>());
                    i = chunk_end;
                }
            }
            _ => checksum = checksum.wrapping_add(raw.iter().map(|b| *b as u64).sum::<u64>()),
        }
        reader.offset = end;
    }
    Ok(checksum)
}

#[cfg(feature = "dns-codec")]
fn build_query(domain: &str) -> Vec<u8> {
    let mut p=Vec::new();
    let h=Header{id:0x1234,mtype:MessageType::Query,qtype:QueryType::Standard,truncated:false,recursion_desired:true,question_count:1,answer_count:0,nameserver_count:0,additional_count:0};
    let q=Question{name:domain,qtype:1,qclass:1};
    let mut w=Writer::new(&mut p); w.write_header(&h); w.write_question(&q); p
}
#[cfg(feature = "dns-codec")]
fn build_a_response(domain: &str) -> Vec<u8> {
    let mut p=Vec::new();
    let h=Header{id:0x1234,mtype:MessageType::Response(ResponseData{authoritative:false,recursion_available:true,error:None}),qtype:QueryType::Standard,truncated:false,recursion_desired:true,question_count:1,answer_count:1,nameserver_count:0,additional_count:0};
    let q=Question{name:domain,qtype:1,qclass:1}; let rr=Resource{name:domain,qtype:1,qclass:1,time_to_live:60,data_len:4};
    let mut w=Writer::new(&mut p); w.write_header(&h); w.write_question(&q); w.write_resource(&rr); w.write(&[203,0,113,7]); p
}
fn main() {
    let mut a=env::args().skip(1); let mode=a.next().unwrap_or_else(||"hash".into()); let path=a.next().expect("input path");
    let bytes=fs::read(path).expect("read runtime input");
    #[cfg(feature = "dns-codec")]
    let out=match mode.as_str(){
      "parse"=>parsed_checksum(&bytes).expect("parse DNS fixture"),
      "write-query"=>{let name=std::str::from_utf8(&bytes).unwrap();let p=build_query(name);parsed_checksum(&p).unwrap()},
      "write-response"=>{let name=std::str::from_utf8(&bytes).unwrap();let p=build_a_response(name);let answer_offset=p.len()-16;assert_eq!(p[answer_offset]&0xc0,0xc0);parsed_checksum(&p).unwrap()},
      _=>bytes.iter().fold(0xcbf29ce484222325u64,|h,b|(h^*b as u64).wrapping_mul(0x100000001b3)),
    };
    #[cfg(not(feature = "dns-codec"))]
    let out=bytes.iter().fold(0xcbf29ce484222325u64,|h,b|(h^*b as u64).wrapping_mul(0x100000001b3));
    println!("{mode}:{out}");
}

#[cfg(all(test,feature="dns-codec"))]
mod tests{
 use super::*;
 fn from_hex(h:&str)->Vec<u8>{(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect()}
 #[test] fn reads_uncompressed_query(){let p=from_hex("123401000001000000000000076578616d706c6503636f6d0000010001");let mut r=Reader::new(&p);let h=r.read_header().unwrap();assert_eq!(h.question_count,1);let q=r.read_question().unwrap();assert_eq!(q.name,"example.com");assert_eq!(q.qtype,1);}
 #[test] fn reads_uncompressed_a_response_and_raw_rdata(){let p=from_hex("123481800001000100000000076578616d706c6503636f6d0000010001076578616d706c6503636f6d00000100010000003c000401020304");let mut r=Reader::new(&p);let _=r.read_header().unwrap();let _=r.read_question().unwrap();let (name,qtype,len)={let rr=r.read_resource().unwrap();(rr.name.to_owned(),rr.qtype,rr.data_len as usize)};assert_eq!(name,"example.com");assert_eq!(qtype,1);assert_eq!(len,4);let start=r.offset;let raw=&r.packet[start..start+len];assert_eq!(raw,&[1,2,3,4]);}
 #[test] fn reads_compressed_a_owner_response_and_raw_rdata(){let p=from_hex("123481800001000100000000076578616d706c6503636f6d0000010001c00c000100010000003c000401020304");let mut r=Reader::new(&p);let _=r.read_header().unwrap();let _=r.read_question().unwrap();let (name,qtype,len)={let rr=r.read_resource().unwrap();(rr.name.to_owned(),rr.qtype,rr.data_len as usize)};assert_eq!(name,"example.com");assert_eq!(qtype,1);let start=r.offset;let raw=&r.packet[start..start+len];assert_eq!(raw,&[1,2,3,4]);}
 #[test] fn reads_compressed_cname_rdata_only_via_manual_read_name(){let p=from_hex("123481800001000100000000076578616d706c6503636f6d0000010001c00c000500010000003c000805616c696173c014");let mut r=Reader::new(&p);let _=r.read_header().unwrap();let _=r.read_question().unwrap();let len={let rr=r.read_resource().unwrap();assert_eq!(rr.qtype,5);rr.data_len as usize};let end=r.offset+len;let cname=r.read_name().unwrap().to_owned();assert_eq!(cname,"alias.com");assert!(r.offset<=end);}
 #[test] fn reads_txt_only_by_manual_length_prefixed_chunk_decode(){let p=from_hex("123481800001000100000000076578616d706c6503636f6d0000010001c00c001000010000003c000c0568656c6c6f05776f726c64");let mut r=Reader::new(&p);let _=r.read_header().unwrap();let _=r.read_question().unwrap();let len={let rr=r.read_resource().unwrap();assert_eq!(rr.qtype,16);rr.data_len as usize};let end=r.offset+len;let mut i=r.offset;let mut chunks=Vec::new();while i<end{let n=r.packet[i] as usize;i+=1;chunks.push(std::str::from_utf8(&r.packet[i..i+n]).unwrap().to_string());i+=n;}assert_eq!(chunks,["hello","world"]);}
 #[test] fn writer_emits_query_and_compresses_repeated_answer_name(){let q=build_query("example.com");assert_eq!(q[12],7);let p=build_a_response("example.com");let mut r=Reader::new(&p);let _=r.read_header().unwrap();let _=r.read_question().unwrap();let rr=r.read_resource().unwrap();assert_eq!(rr.name,"example.com");let answer_offset=q.len();assert_eq!(&p[answer_offset..answer_offset+2],&[0xc0,0x0c]);}
 #[test] fn pointer_to_pointer_is_not_supported(){let p=from_hex("123481800001000200000000076578616d706c6503636f6d0000010001c00c000100010000003c000401020304c01d00010001000000010004cb007108");let mut r=Reader::new(&p);let _=r.read_header().unwrap();let _=r.read_question().unwrap();let first=r.read_resource().unwrap();let len=first.data_len as usize;let _=first;r.offset+=len;assert!(r.read_resource().is_none());}
}
